/*******************************************************************************
 * Size: 24 px
 * Bpp: 1
 * Opts: --no-compress --no-prefilter --bpp 1 --size 24 --font /tmp/DroidSansFallback.ttf -r 0x20-0x7F --symbols 的一是了我不人在他有这上们来到时大地为子中你说生国年着就那和要出也得里后自以会家可下而过天去能对小多然于心学之都好看起发当没成只如事把还用第样道想作种开美总从无情己面最女但现前些所同日手又行意动方期它头经长儿回位分爱老因很给名法间斯知世什两次使身者被高已亲其进此话常与活正感见明问力理尔点文几定本公特做外孩相西果走将月十实向声车全信重三机工物气每并别真打太新比才便夫再书部水像眼等体却加电主界门利海受听表德少克代员先口由死安写性马光白或住难望教命花结乐色更拉东神记处让母父应直字场平报友关放至张认接告入笑内军候民岁往何度山觉路带万男边风解叫任金快原吃妈变通师立象数四失满战远格士音轻目条呢病始达深完今提求清王化空业思切怎非找片罗钱语元喜曾离飞科言干流欢约各即指合反题必该论交终林请医晚制球决传画保读运及则房早院量苦火布品近坐产答星精视五连司巴奇管类未朋且台背油察绝状考拍板错梳需构建镜模拟器宠矢素材资源形双槽净室件录码编译烧屏幕按键协议链执查删除创修改待响绪闭存搜索复粘贴移测试调署装启停止功败误警示确取消返刷输设备服务客户网络端址据志版支推送仓库权限证密脚令参函组线程队列缓冲驱固硬软架块依赖框例优压缩图频辨率横竖景颜黑红绿蓝黄紫灰亮暗个秒周浏览页左右居齐距系统标智助嗯继续束暂串芯伸裁剪拒允许撤销授策短触排座载区序滤映射轮播闪呼吸伏抖汗滴环绕导步延迟稳预算超泄漏暴露险枚举断覆盖退兜底迭碑辩演份拆包禁境配置缺省阈值符号径注释 --format lvgl --force-fast-kern-format -o main/font_pet_text_24.c
 ******************************************************************************/

